edits.content:
version: 2
unit_tests:
  - name: customer_rollup_preserves_empty_and_all_statuses
    model: dim_customers
    given:
      - input: ref('stg_customers')
        rows:
          - {customer_id: 1, country_code: IT, signup_date: '2024-01-01'}
          - {customer_id: 2, country_code: DE, signup_date: '2024-01-02'}
          - {customer_id: 3, country_code: FR, signup_date: '2024-01-03'}
      - input: ref('stg_orders')
        rows:
          - {order_id: 1, customer_id: 1, status: paid, order_total: 10, ordered_at: '2024-02-01 12:00:00'}
          - {order_id: 2, customer_id: 1, status: cancelled, order_total: 25, ordered_at: '2024-02-02 12:00:00'}
          - {order_id: 3, customer_id: 2, status: placed, order_total: 7, ordered_at: '2024-02-03 12:00:00'}
    expect:
      rows:
        - {customer_id: 1, country_code: IT, signup_date: '2024-01-01', order_count: 2, booked_amount: 35}
        - {customer_id: 2, country_code: DE, signup_date: '2024-01-02', order_count: 1, booked_amount: 7}
        - {customer_id: 3, country_code: FR, signup_date: '2024-01-03', order_count: 0, booked_amount: 0}

with expected as (
 select order_id, customer_id, status, order_total, cast(placed_at as timestamp) as ordered_at from {{ source('demo', 'orders') }}
), differences as (
 (select * from expected except all select * from {{ ref('stg_orders') }})
 union all
 (select * from {{ ref('stg_orders') }} except all select * from expected)
)
select * from differences

select count(*) as days from {{ ref('metricflow_time_spine') }}
having count(*) <> 5844 or min(date_day) <> date '2020-01-01' or max(date_day) <> date '2035-12-31'
 or count(distinct date_day) <> count(*)
